class LuaNilType:
    __slots__ = ()

    def __repr__(self) -> str:
        return "nil"


NIL = LuaNilType()


def is_nil(value: Any) -> bool:
    return value is NIL


def truthy(value: Any) -> bool:
    return value is not NIL and value is not False


def canonical_key(key: Any) -> Any:
    if key is NIL:
        raise LuaRuntimeError("table index is nil")
    if isinstance(key, float):
        if _math.isnan(key):
            raise LuaRuntimeError("table index is NaN")
        if key.is_integer():
            return int(key)
    return key


def int64(value: int) -> int:
    value &= (1 << 64) - 1
    if value >= 1 << 63:
        value -= 1 << 64
    return value


class LuaError(Exception):
    pass


class LuaParseError(LuaError):
    def __init__(
        self,
        source: str,
        line: int,
        message: str,
        near: Optional[str] = None,
        incomplete: bool = False,
    ) -> None:
        self.source = source
        self.line = line
        self.message = message
        self.near = near
        self.incomplete = incomplete
        super().__init__(self.format_message())

    def format_message(self) -> str:
        if self.near is None:
            return f"{self.source}:{self.line}: {self.message}"
        return f"{self.source}:{self.line}: {self.message} near {self.near}"


