@dataclass
class Token:
    kind: str
    value: str
    line: int
    col: int
    pos: int
    end: int


KEYWORDS = {
    "and",
    "break",
    "do",
    "else",
    "elseif",
    "end",
    "false",
    "for",
    "function",
    "goto",
    "if",
    "in",
    "local",
    "nil",
    "not",
    "or",
    "repeat",
    "return",
    "then",
    "true",
    "until",
    "while",
}

MULTI_OPERATORS = [
    "...",
    "//",
    "<<",
    ">>",
    "<=",
    ">=",
    "==",
    "~=",
    "::",
    "..",
]


class Lexer:
    def __init__(self, source_name: str, text: str) -> None:
        self.source_name = source_name
        self.text = text
        self.length = len(text)
        self.pos = 0
        self.line = 1
        self.line_start = 0

    def tokenize(self) -> list[Token]:
        tokens: list[Token] = []
        while True:
            self.skip_ws_comments()
            if self.pos >= self.length:
                tokens.append(self.make_token("EOF", "", self.pos, self.pos))
                return tokens
            start = self.pos
            ch = self.text[self.pos]
            if ch.isalpha() or ch == "_":
                tokens.append(self.lex_name())
                continue
            if ch.isdigit() or (ch == "." and self.pos + 1 < self.length and self.text[self.pos + 1].isdigit()):
                token = self.lex_number()
                if token is not None:
                    tokens.append(token)
                    continue
            if ch in "\"'":
                tokens.append(self.lex_short_string(ch))
                continue
            if ch == "[":
                long = self.try_long_string()
                if long is not None:
                    tokens.append(long)
                    continue
            matched = False
            for op in MULTI_OPERATORS:
                if self.text.startswith(op, self.pos):
                    self.advance(op)
                    tokens.append(self.make_token(op, op, start, self.pos))
                    matched = True
                    break
            if matched:
                continue
            self.advance(ch)
            tokens.append(self.make_token(ch, ch, start, self.pos))

    def make_token(self, kind: str, value: str, start: int, end: int) -> Token:
        line = self.text.count("\n", 0, start) + 1
        last_nl = self.text.rfind("\n", 0, start)
        col = start + 1 if last_nl < 0 else start - last_nl
        return Token(kind, value, line, col, start, end)

    def skip_ws_comments(self) -> None:
        while self.pos < self.length:
            ch = self.text[self.pos]
            if ch in " \t\r\f\v":
                self.advance(ch)
                continue
            if ch == "\n":
                self.advance(ch)
                continue
            if self.text.startswith("--", self.pos):
                self.advance("--")
                if self.pos < self.length and self.text[self.pos] == "[":
                    if self.skip_long_string(comment=True):
                        continue
                while self.pos < self.length and self.text[self.pos] != "\n":
                    self.advance(self.text[self.pos])
                continue
            break

    def advance(self, text: str) -> None:
        for ch in text:
            if ch == "\n":
                self.line += 1
                self.line_start = self.pos + 1
            self.pos += 1

    def lex_name(self) -> Token:
        start = self.pos
        while self.pos < self.length and (self.text[self.pos].isalnum() or self.text[self.pos] == "_"):
            self.advance(self.text[self.pos])
        value = self.text[start : self.pos]
        kind = value if value in KEYWORDS else "NAME"
        return self.make_token(kind, value, start, self.pos)

    def lex_number(self) -> Optional[Token]:
        start = self.pos
        rest = self.text[self.pos :]
        number_re = re.compile(
            r"0[xX](?:[0-9A-Fa-f]+(?:\.[0-9A-Fa-f]*)?|\.[0-9A-Fa-f]+)(?:[pP][+\-]?[0-9]+)?"
            r"|0[xX][0-9A-Fa-f]+"
            r"|(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+\-]?[0-9]+)?"
        )
        match = number_re.match(rest)
        if not match:
            return None
        text = match.group(0)
        self.advance(text)
        return self.make_token("NUMBER", text, start, self.pos)

    def lex_short_string(self, quote: str) -> Token:
        start = self.pos
        self.advance(quote)
        out: list[str] = []
        while self.pos < self.length:
            ch = self.text[self.pos]
            if ch == quote:
                self.advance(ch)
                return self.make_token("STRING", "".join(out), start, self.pos)
            if ch == "\n":
                raise LuaParseError(self.source_name, self.line, "unfinished string")
            if ch != "\\":
                out.append(ch)
                self.advance(ch)
                continue
            self.advance("\\")
            if self.pos >= self.length:
                raise LuaParseError(self.source_name, self.line, "unfinished string")
            esc = self.text[self.pos]
            self.advance(esc)
            if esc == "a":
                out.append("\a")
            elif esc == "b":
                out.append("\b")
            elif esc == "f":
                out.append("\f")
            elif esc == "n":
                out.append("\n")
            elif esc == "r":
                out.append("\r")
            elif esc == "t":
                out.append("\t")
            elif esc == "v":
                out.append("\v")
            elif esc in "\\\"'":
                out.append(esc)
            elif esc == "z":
                while self.pos < self.length and self.text[self.pos].isspace():
                    self.advance(self.text[self.pos])
            elif esc == "x":
                digits = self.text[self.pos : self.pos + 2]
                if len(digits) < 2 or not re.fullmatch(r"[0-9A-Fa-f]{2}", digits):
                    raise LuaParseError(self.source_name, self.line, "hexadecimal digit expected")
                self.advance(digits)
                out.append(chr(int(digits, 16)))
            elif esc == "u":
                if self.pos >= self.length or self.text[self.pos] != "{":
                    raise LuaParseError(self.source_name, self.line, "missing '{' in \\u escape")
                self.advance("{")
                end = self.text.find("}", self.pos)
                if end < 0:
                    raise LuaParseError(self.source_name, self.line, "missing '}' in \\u escape")
                digits = self.text[self.pos : end]
                if not digits or not re.fullmatch(r"[0-9A-Fa-f]+", digits):
                    raise LuaParseError(self.source_name, self.line, "hexadecimal digit expected")
                self.advance(digits + "}")
                out.append(chr(int(digits, 16)))
            elif esc in "\n\r":
                if esc == "\r" and self.pos < self.length and self.text[self.pos] == "\n":
                    self.advance("\n")
                out.append("\n")
            elif esc.isdigit():
                digits = esc
                while self.pos < self.length and len(digits) < 3 and self.text[self.pos].isdigit():
                    digits += self.text[self.pos]
                    self.advance(self.text[self.pos])
                out.append(chr(int(digits, 10)))
            else:
                out.append(esc)
        raise LuaParseError(self.source_name, self.line, "unfinished string")

    def long_string_level(self, pos: int) -> Optional[int]:
        if pos >= self.length or self.text[pos] != "[":
            return None
        i = pos + 1
        level = 0
        while i < self.length and self.text[i] == "=":
            level += 1
            i += 1
        if i < self.length and self.text[i] == "[":
            return level
        return None

    def skip_long_string(self, comment: bool = False) -> bool:
        level = self.long_string_level(self.pos)
        if level is None:
            return False
        open_len = 2 + level
        start_line = self.line
        self.advance(self.text[self.pos : self.pos + open_len])
        if self.pos < self.length and self.text[self.pos] == "\n":
            self.advance("\n")
        close = "]" + ("=" * level) + "]"
        end = self.text.find(close, self.pos)
        if end < 0:
            raise LuaParseError(self.source_name, start_line, "unfinished long string")
        content = self.text[self.pos : end]
        self.advance(content)
        self.advance(close)
        return True

    def try_long_string(self) -> Optional[Token]:
        level = self.long_string_level(self.pos)
        if level is None:
            return None
        start = self.pos
        open_len = 2 + level
        self.advance(self.text[self.pos : self.pos + open_len])
        if self.pos < self.length and self.text[self.pos] == "\n":
            self.advance("\n")
        close = "]" + ("=" * level) + "]"
        end = self.text.find(close, self.pos)
        if end < 0:
            raise LuaParseError(self.source_name, self.line, "unfinished long string")
        content = self.text[self.pos : end]
        self.advance(content)
        self.advance(close)
        return self.make_token("STRING", content, start, self.pos)


