PRECEDENCE = {
    "or": 1,
    "and": 2,
    "<": 3,
    ">": 3,
    "<=": 3,
    ">=": 3,
    "~=": 3,
    "==": 3,
    "|": 4,
    "~": 5,
    "&": 6,
    "<<": 7,
    ">>": 7,
    "..": 8,
    "+": 9,
    "-": 9,
    "*": 10,
    "/": 10,
    "//": 10,
    "%": 10,
    "^": 12,
}
RIGHT_ASSOC = {"^", ".."}
UNARY_PRECEDENCE = 11


class Parser:
    def __init__(self, source_name: str, text: str) -> None:
        self.source_name = source_name
        self.text = text
        self.tokens = Lexer(source_name, text).tokenize()
        self.index = 0
        self.local_scopes: list[dict[str, str]] = [{}]

    def current(self) -> Token:
        return self.tokens[self.index]

    def next(self) -> Token:
        tok = self.current()
        self.index += 1
        return tok

    def match(self, *kinds: str) -> Optional[Token]:
        tok = self.current()
        if tok.kind in kinds:
            self.index += 1
            return tok
        return None

    def expect(self, kind: str) -> Token:
        tok = self.current()
        if tok.kind != kind:
            if tok.kind == "EOF":
                raise LuaParseError(
                    self.source_name,
                    tok.line,
                    f"'{kind}' expected",
                    near="<eof>",
                    incomplete=True,
                )
            raise LuaParseError(self.source_name, tok.line, f"'{kind}' expected", near=repr(tok.value))
        self.index += 1
        return tok

    def parse(self) -> Chunk:
        block = self.parse_block(stop_words={"EOF"})
        self.expect("EOF")
        return Chunk(block.line, block, self.source_name, self.text)

    def push_scope(self) -> None:
        self.local_scopes.append({})

    def pop_scope(self) -> None:
        self.local_scopes.pop()

    def declare_names(self, names: list[str], attrs: list[str]) -> None:
        for name, attr in zip(names, attrs):
            self.local_scopes[-1][name] = attr

    def lookup_local_attr(self, name: str) -> Optional[str]:
        for scope in reversed(self.local_scopes):
            if name in scope:
                return scope[name]
        return None

    def parse_block(self, stop_words: set[str]) -> Block:
        start_line = self.current().line
        statements: list[Node] = []
        returns: Optional[list[Expr]] = None
        while self.current().kind not in stop_words:
            if self.match(";"):
                continue
            if self.current().kind == "return":
                ret = self.next()
                values: list[Expr] = []
                if self.current().kind not in {"EOF", "end", "elseif", "else", "until", ";"}:
                    values = self.parse_explist()
                self.match(";")
                returns = values
                break
            statements.append(self.parse_statement())
        return Block(start_line, statements, returns)

    def parse_statement(self) -> Node:
        tok = self.current()
        if tok.kind == "if":
            return self.parse_if()
        if tok.kind == "while":
            return self.parse_while()
        if tok.kind == "repeat":
            return self.parse_repeat()
        if tok.kind == "do":
            return self.parse_do()
        if tok.kind == "for":
            return self.parse_for()
        if tok.kind == "break":
            self.next()
            return BreakStmt(tok.line)
        if tok.kind == "goto":
            self.next()
            label = self.expect("NAME")
            return GotoStmt(tok.line, label.value)
        if tok.kind == "::":
            self.next()
            label = self.expect("NAME")
            self.expect("::")
            return LabelStmt(tok.line, label.value)
        if tok.kind == "function":
            return self.parse_function_statement()
        if tok.kind == "local":
            return self.parse_local_statement()
        expr = self.parse_prefixexp()
        if isinstance(expr, CallExpr):
            return CallStmt(expr.line, expr)
        targets = [self.ensure_lvalue(expr)]
        while self.match(","):
            targets.append(self.ensure_lvalue(self.parse_prefixexp()))
        self.expect("=")
        values = self.parse_explist()
        for target in targets:
            if isinstance(target, Name):
                attr = self.lookup_local_attr(target.id)
                if attr == "const":
                    raise LuaParseError(self.source_name, target.line, f"attempt to assign to const variable '{target.id}'")
        return Assign(tok.line, targets, values)

    def parse_if(self) -> IfStmt:
        tok = self.expect("if")
        branches: list[tuple[Expr, Block]] = []
        cond = self.parse_exp()
        self.expect("then")
        self.push_scope()
        block = self.parse_block({"elseif", "else", "end"})
        self.pop_scope()
        branches.append((cond, block))
        while self.match("elseif"):
            cond = self.parse_exp()
            self.expect("then")
            self.push_scope()
            block = self.parse_block({"elseif", "else", "end"})
            self.pop_scope()
            branches.append((cond, block))
        else_block: Optional[Block] = None
        if self.match("else"):
            self.push_scope()
            else_block = self.parse_block({"end"})
            self.pop_scope()
        self.expect("end")
        return IfStmt(tok.line, branches, else_block)

    def parse_while(self) -> WhileStmt:
        tok = self.expect("while")
        cond = self.parse_exp()
        self.expect("do")
        self.push_scope()
        block = self.parse_block({"end"})
        self.pop_scope()
        self.expect("end")
        return WhileStmt(tok.line, cond, block)

    def parse_repeat(self) -> RepeatStmt:
        tok = self.expect("repeat")
        self.push_scope()
        block = self.parse_block({"until"})
        self.expect("until")
        cond = self.parse_exp()
        self.pop_scope()
        return RepeatStmt(tok.line, block, cond)

    def parse_do(self) -> DoStmt:
        tok = self.expect("do")
        self.push_scope()
        block = self.parse_block({"end"})
        self.pop_scope()
        self.expect("end")
        return DoStmt(tok.line, block)

    def parse_for(self) -> Node:
        tok = self.expect("for")
        name = self.expect("NAME")
        attr = self.parse_optional_attr()
        if self.match("="):
            start = self.parse_exp()
            self.expect(",")
            stop = self.parse_exp()
            step = self.parse_exp() if self.match(",") else None
            self.expect("do")
            self.push_scope()
            self.declare_names([name.value], ["const"])
            block = self.parse_block({"end"})
            self.pop_scope()
            self.expect("end")
            return NumericFor(tok.line, name.value, "const", start, stop, step, block)
        names = [name.value]
        attrs = [attr]
        while self.match(","):
            nm = self.expect("NAME")
            names.append(nm.value)
            attrs.append(self.parse_optional_attr())
        self.expect("in")
        values = self.parse_explist()
        self.expect("do")
        self.push_scope()
        self.declare_names(names, ["const" for _ in names])
        block = self.parse_block({"end"})
        self.pop_scope()
        self.expect("end")
        return GenericFor(tok.line, names, attrs, values, block)

    def parse_function_statement(self) -> FunctionAssign:
        tok = self.expect("function")
        first = self.expect("NAME")
        path = [first.value]
        method_name: Optional[str] = None
        while self.match("."):
            path.append(self.expect("NAME").value)
        if self.match(":"):
            method_name = self.expect("NAME").value
        body = self.parse_function_body(extra_self=method_name is not None)
        return FunctionAssign(tok.line, path, body, method_name)

    def parse_local_statement(self) -> Node:
        tok = self.expect("local")
        if self.match("function"):
            name = self.expect("NAME")
            self.local_scopes[-1][name.value] = ""
            body = self.parse_function_body()
            return LocalFunction(tok.line, name.value, body)
        names = [self.expect("NAME").value]
        attrs = [self.parse_optional_attr()]
        while self.match(","):
            names.append(self.expect("NAME").value)
            attrs.append(self.parse_optional_attr())
        values: list[Expr] = []
        if self.match("="):
            values = self.parse_explist()
        self.declare_names(names, attrs)
        return LocalAssign(tok.line, names, attrs, values)

    def parse_optional_attr(self) -> str:
        if not self.match("<"):
            return ""
        name = self.expect("NAME")
        self.expect(">")
        return name.value

    def parse_function_body(self, extra_self: bool = False) -> FunctionBody:
        start_tok = self.expect("(")
        params: list[str] = []
        attrs: list[str] = []
        vararg = False
        self.push_scope()
        if not self.match(")"):
            if self.match("..."):
                vararg = True
            else:
                while True:
                    name = self.expect("NAME")
                    params.append(name.value)
                    attrs.append(self.parse_optional_attr())
                    if not self.match(","):
                        break
                    if self.match("..."):
                        vararg = True
                        break
                self.expect(")")
            if self.current().kind != ")":
                pass
        if self.tokens[self.index - 1].kind != ")":
            self.expect(")")
        if extra_self:
            params = ["self"] + params
            attrs = [""] + attrs
        self.declare_names(params, attrs)
        block = self.parse_block({"end"})
        end_tok = self.expect("end")
        self.pop_scope()
        return FunctionBody(start_tok.line, params, attrs, vararg, block, start_tok.pos, end_tok.end)

    def parse_explist(self) -> list[Expr]:
        items = [self.parse_exp()]
        while self.match(","):
            items.append(self.parse_exp())
        return items

    def parse_exp(self, min_prec: int = 0) -> Expr:
        tok = self.current()
        if tok.kind in {"nil", "true", "false", "NUMBER", "STRING", "...", "{", "function"}:
            left = self.parse_simpleexp()
        elif tok.kind in {"-", "not", "#", "~"}:
            self.next()
            left = UnaryOp(tok.line, tok.kind, self.parse_exp(UNARY_PRECEDENCE))
        else:
            left = self.parse_prefixexp()
        while True:
            tok = self.current()
            op = tok.kind
            if op not in PRECEDENCE:
                break
            prec = PRECEDENCE[op]
            if prec < min_prec:
                break
            self.next()
            next_min = prec if op in RIGHT_ASSOC else prec + 1
            right = self.parse_exp(next_min)
            left = BinaryOp(left.line, left, op, right)
        return left

    def parse_simpleexp(self) -> Expr:
        tok = self.current()
        if tok.kind == "nil":
            self.next()
            return Literal(tok.line, NIL)
        if tok.kind == "true":
            self.next()
            return Literal(tok.line, True)
        if tok.kind == "false":
            self.next()
            return Literal(tok.line, False)
        if tok.kind == "NUMBER":
            self.next()
            return Literal(tok.line, parse_number_literal(tok.value))
        if tok.kind == "STRING":
            self.next()
            return Literal(tok.line, tok.value)
        if tok.kind == "...":
            self.next()
            return VarArg(tok.line)
        if tok.kind == "{":
            return self.parse_tableconstructor()
        if tok.kind == "function":
            self.next()
            return FunctionDef(tok.line, self.parse_function_body())
        raise LuaParseError(self.source_name, tok.line, "unexpected symbol", near=repr(tok.value))

    def parse_tableconstructor(self) -> TableConstructor:
        tok = self.expect("{")
        fields: list[TableField] = []
        while self.current().kind != "}":
            if self.match("["):
                key = self.parse_exp()
                self.expect("]")
                self.expect("=")
                value = self.parse_exp()
                fields.append(TableField("expr", key, value, key.line))
            elif self.current().kind == "NAME" and self.tokens[self.index + 1].kind == "=":
                name = self.next()
                self.expect("=")
                value = self.parse_exp()
                fields.append(TableField("name", Literal(name.line, name.value), value, name.line))
            else:
                value = self.parse_exp()
                fields.append(TableField("array", None, value, value.line))
            if not self.match(",") and not self.match(";"):
                break
        self.expect("}")
        return TableConstructor(tok.line, fields)

    def parse_prefixexp(self) -> Expr:
        tok = self.current()
        if tok.kind == "NAME":
            expr: Expr = Name(tok.line, self.next().value)
        elif tok.kind == "(":
            self.next()
            expr = ParenExpr(tok.line, self.parse_exp())
            self.expect(")")
        else:
            raise LuaParseError(self.source_name, tok.line, "unexpected symbol", near=repr(tok.value))
        while True:
            tok = self.current()
            if self.match("["):
                key = self.parse_exp()
                self.expect("]")
                expr = IndexExpr(expr.line, expr, key)
                continue
            if self.match("."):
                name = self.expect("NAME")
                expr = FieldExpr(expr.line, expr, name.value)
                continue
            if self.match(":"):
                name = self.expect("NAME")
                args = self.parse_args()
                expr = CallExpr(expr.line, expr, args, name.value)
                continue
            if tok.kind in {"(", "{", "STRING"}:
                args = self.parse_args()
                expr = CallExpr(expr.line, expr, args)
                continue
            break
        return expr

    def parse_args(self) -> list[Expr]:
        if self.match("("):
            args: list[Expr] = []
            if self.current().kind != ")":
                args = self.parse_explist()
            self.expect(")")
            return args
        if self.current().kind == "{":
            return [self.parse_tableconstructor()]
        if self.current().kind == "STRING":
            tok = self.next()
            return [Literal(tok.line, tok.value)]
        tok = self.current()
        raise LuaParseError(self.source_name, tok.line, "function arguments expected", near=repr(tok.value))

    def ensure_lvalue(self, expr: Expr) -> Expr:
        if isinstance(expr, (Name, IndexExpr, FieldExpr)):
            return expr
        raise LuaParseError(self.source_name, expr.line, "syntax error")


def parse_number_literal(text: str) -> Any:
    if text.lower().startswith("0x"):
        if "p" in text.lower() or "." in text:
            return float.fromhex(text)
        return int(text, 16)
    if any(ch in text for ch in ".eE"):
        return float(text)
    return int(text, 10)


@dataclass
class Cell:
    value: Any = NIL
    attr: str = ""
    name: str = ""


class Scope:
    def __init__(self, runtime: "Runtime", env: "LuaTable", parent: Optional["Scope"] = None) -> None:
        self.runtime = runtime
        self.env = env
        self.parent = parent
        self.locals: dict[str, Cell] = {}
        self.close_order: list[Cell] = []

    def define(self, name: str, value: Any = NIL, attr: str = "") -> Cell:
        cell = Cell(value, attr, name)
        self.locals[name] = cell
        if attr == "close":
            self.close_order.append(cell)
        return cell

    def lookup_cell(self, name: str) -> Optional[Cell]:
        scope: Optional[Scope] = self
        while scope is not None:
            if name in scope.locals:
                return scope.locals[name]
            scope = scope.parent
        return None

    def get(self, name: str) -> Any:
        if name == "_ENV":
            return self.env
        cell = self.lookup_cell(name)
        if cell is not None:
            return cell.value
        return self.runtime.table_get(self.env, name)

    def set(self, name: str, value: Any) -> None:
        if name == "_ENV":
            raise LuaRuntimeError("attempt to assign to _ENV")
        cell = self.lookup_cell(name)
        if cell is not None:
            if cell.attr == "const":
                raise LuaRuntimeError(f"attempt to assign to const variable '{name}'")
            cell.value = value
            return
        self.runtime.table_set(self.env, name, value)

    def close(self, err: Any = NIL) -> Generator[Any, list[Any], None]:
        for cell in reversed(self.close_order):
            value = cell.value
            if value is NIL:
                continue
            mt = self.runtime.get_metamethod(value, "__close")
            if mt is not NIL:
                yield from self.runtime.call(mt, [value, err], None)


class LuaTable:
    def __init__(self) -> None:
        self.values: OrderedDict[Any, Any] = OrderedDict()
        self.metatable: Optional["LuaTable"] = None

    def rawget(self, key: Any) -> Any:
        key = canonical_key(key)
        return self.values.get(key, NIL)

    def rawset(self, key: Any, value: Any) -> None:
        key = canonical_key(key)
        if value is NIL:
            self.values.pop(key, None)
        else:
            self.values[key] = value

    def length(self) -> int:
        i = 0
        while True:
            nxt = i + 1
            if self.rawget(nxt) is NIL:
                return i
            i = nxt

    def rawlen(self) -> int:
        return self.length()

    def __repr__(self) -> str:
        return f"<LuaTable {id(self):x}>"


class LuaCallable:
    pass


class BuiltinFunction(LuaCallable):
    def __init__(self, name: str, func: Callable[..., Any], kind: str = "global") -> None:
        self.name = name
        self.func = func
        self.kind = kind

    def __repr__(self) -> str:
        return f"<BuiltinFunction {self.name}>"


class LuaFunction(LuaCallable):
    def __init__(
        self,
        runtime: "Runtime",
        body: FunctionBody,
        scope: Scope,
        source_name: str,
        source_text: str,
        display_name: Optional[str] = None,
    ) -> None:
        self.runtime = runtime
        self.body = body
        self.scope = scope
        self.source_name = source_name
        self.source_text = source_text
        self.display_name = display_name
        self.dump_source = source_text[body.start_pos - 8 : body.end_pos] if body.end_pos <= len(source_text) else None

    def __repr__(self) -> str:
        return f"<LuaFunction {id(self):x}>"


class LuaThread:
    def __init__(self, runtime: "Runtime", func: LuaCallable, parent_env: LuaTable) -> None:
        self.runtime = runtime
        self.func = func
        self.parent_env = parent_env
        self.status = "suspended"
        self.generator: Optional[Generator[Any, list[Any], list[Any]]] = None
        self.dead = False
        self.current_args: list[Any] = []

    def __repr__(self) -> str:
        return f"<LuaThread {id(self):x}>"


@dataclass
class Frame:
    source_name: str
    line: int
    name: str
    kind: str
    is_c: bool = False


class Runtime:
    def __init__(self, argv0: str, stdin: Any, stdout: Any, stderr: Any, warnings_enabled: bool = False) -> None:
        self.argv0 = argv0
        self.stdin = stdin
        self.stdout = stdout
        self.stderr = stderr
        self.warnings_enabled = warnings_enabled
        self.warning_state = True
        self.globals = LuaTable()
        self.package = LuaTable()
        self.string_table = LuaTable()
        self.table_table = LuaTable()
        self.math_table = LuaTable()
        self.coroutine_table = LuaTable()
        self.io_table = LuaTable()
        self.os_table = LuaTable()
        self.debug_table = LuaTable()
        self.utf8_table = LuaTable()
        self.random = random.Random()
        self.call_stack: list[Frame] = []
        self.main_thread = LuaThread(self, BuiltinFunction("main", lambda *_: []), self.globals)
        self.current_thread = self.main_thread
        self.string_metatable = LuaTable()
        self.install_builtins()

    def push_frame(self, source_name: str, line: int, name: str, kind: str, is_c: bool = False) -> None:
        self.call_stack.append(Frame(source_name, line, name, kind, is_c))

    def pop_frame(self) -> None:
        if self.call_stack:
            self.call_stack.pop()

    def current_frame(self) -> Optional[Frame]:
        return self.call_stack[-1] if self.call_stack else None

    def set_line(self, line: int) -> None:
        frame = self.current_frame()
        if frame is not None:
            frame.line = line

    def snapshot_stack(self) -> list[Frame]:
        return [dataclasses.replace(frame) for frame in self.call_stack]

    def raise_error(self, message: Any) -> None:
        raise LuaRuntimeError(message, self.snapshot_stack())

    def builtin(self, table: LuaTable, name: str, func: Callable[..., Any], kind: str = "field") -> BuiltinFunction:
        built = BuiltinFunction(name, func, kind)
        table.rawset(name, built)
        return built

    def install_builtins(self) -> None:
        g = self.globals
        g.rawset("_G", g)
        g.rawset("_VERSION", VERSION_SHORT)
        g.rawset("arg", LuaTable())
        self.builtin(g, "print", self.lib_print, "global")
        self.builtin(g, "type", self.lib_type, "global")
        self.builtin(g, "tostring", self.lib_tostring, "global")
        self.builtin(g, "tonumber", self.lib_tonumber, "global")
        self.builtin(g, "assert", self.lib_assert, "global")
        self.builtin(g, "error", self.lib_error, "global")
        self.builtin(g, "pcall", self.lib_pcall, "global")
        self.builtin(g, "xpcall", self.lib_xpcall, "global")
        self.builtin(g, "warn", self.lib_warn, "global")
        self.builtin(g, "next", self.lib_next, "global")
        self.builtin(g, "pairs", self.lib_pairs, "global")
        self.builtin(g, "ipairs", self.lib_ipairs, "global")
        self.builtin(g, "rawequal", self.lib_rawequal, "global")
        self.builtin(g, "rawget", self.lib_rawget, "global")
        self.builtin(g, "rawset", self.lib_rawset, "global")
        self.builtin(g, "rawlen", self.lib_rawlen, "global")
        self.builtin(g, "setmetatable", self.lib_setmetatable, "global")
        self.builtin(g, "getmetatable", self.lib_getmetatable, "global")
        self.builtin(g, "select", self.lib_select, "global")
        self.builtin(g, "dofile", self.lib_dofile, "global")
        self.builtin(g, "load", self.lib_load, "global")
        self.builtin(g, "loadfile", self.lib_loadfile, "global")
        self.builtin(g, "require", self.lib_require, "global")
        self.builtin(g, "collectgarbage", self.lib_collectgarbage, "global")
        g.rawset("string", self.string_table)
        g.rawset("table", self.table_table)
        g.rawset("math", self.math_table)
        g.rawset("coroutine", self.coroutine_table)
        g.rawset("package", self.package)
        g.rawset("io", self.io_table)
        g.rawset("os", self.os_table)
        g.rawset("debug", self.debug_table)
        g.rawset("utf8", self.utf8_table)
        self.string_metatable.rawset("__index", self.string_table)
        self.install_table_lib()
        self.install_math_lib()
        self.install_string_lib()
        self.install_package_lib()
        self.install_coroutine_lib()
        self.install_io_lib()
        self.install_os_lib()
        self.install_debug_lib()
        self.install_utf8_lib()

    def install_table_lib(self) -> None:
