    def wrap_py_numeric(self, func: Callable[..., Any], name: str) -> Callable[..., Any]:
        def inner(*args: Any) -> Any:
            nums = [self.to_number(arg) for arg in args]
            try:
                return func(*nums)
            except Exception as exc:
                raise LuaRuntimeError(f"bad argument to '{name}' ({exc})", self.snapshot_stack())

        return inner

    def arg_error(self, fname: str, index: int, expected: str, got: Any) -> None:
        got_name = lua_type_name(got)
        self.raise_error(f"bad argument #{index} to '{fname}' ({expected}, got {got_name})")

    def to_number(self, value: Any, integer: bool = False, base: Optional[int] = None) -> Any:
        if isinstance(value, bool) or value is NIL:
            raise LuaRuntimeError(f"attempt to perform arithmetic on a '{lua_type_name(value)}'", self.snapshot_stack())
        if isinstance(value, (int, float)):
            if integer:
                if isinstance(value, float):
                    if not value.is_integer():
                        raise LuaRuntimeError("number has no integer representation", self.snapshot_stack())
                    return int(value)
                return int(value)
            return value
        if isinstance(value, str):
            num = lua_tonumber(value, base)
            if num is None:
                raise LuaRuntimeError(
                    f"attempt to perform arithmetic on a '{lua_type_name(value)}'",
                    self.snapshot_stack(),
                )
            if integer and isinstance(num, float):
                if not num.is_integer():
                    raise LuaRuntimeError("number has no integer representation", self.snapshot_stack())
                return int(num)
            return num
        raise LuaRuntimeError(f"attempt to perform arithmetic on a '{lua_type_name(value)}'", self.snapshot_stack())

    def compare_error(self, left: Any, right: Any) -> None:
        self.raise_error(f"attempt to compare {lua_type_name(left)} with {lua_type_name(right)}")

    def get_metatable(self, value: Any) -> Optional[LuaTable]:
        if isinstance(value, LuaTable):
            return value.metatable
        if isinstance(value, str):
            return self.string_metatable
        return None

    def get_metamethod(self, value: Any, name: str) -> Any:
        mt = self.get_metatable(value)
        if mt is None:
            return NIL
        protected = mt.rawget(name)
        return protected

    def table_get(self, table: Any, key: Any) -> Any:
        if isinstance(table, LuaTable):
            raw = table.rawget(key)
            if raw is not NIL:
                return raw
            mt = table.metatable
            if mt is not None:
                idx = mt.rawget("__index")
                if idx is not NIL:
                    if isinstance(idx, LuaTable):
                        return self.table_get(idx, key)
                    result = self.run_call(idx, [table, key])
                    return result[0] if result else NIL
            return NIL
        mt = self.get_metatable(table)
        if mt is not None:
            idx = mt.rawget("__index")
            if idx is not NIL:
                if isinstance(idx, LuaTable):
                    return self.table_get(idx, key)
                result = self.run_call(idx, [table, key])
                return result[0] if result else NIL
        self.raise_error(f"attempt to index a {lua_type_name(table)} value")

    def table_set(self, table: Any, key: Any, value: Any) -> None:
        if isinstance(table, LuaTable):
            raw = table.rawget(key)
            if raw is not NIL or table.metatable is None or table.metatable.rawget("__newindex") is NIL:
                table.rawset(key, value)
                return
            mm = table.metatable.rawget("__newindex")
            if isinstance(mm, LuaTable):
                self.table_set(mm, key, value)
                return
            self.run_call(mm, [table, key, value])
            return
        mt = self.get_metatable(table)
        if mt is not None:
            mm = mt.rawget("__newindex")
            if mm is not NIL:
                if isinstance(mm, LuaTable):
                    self.table_set(mm, key, value)
                else:
                    self.run_call(mm, [table, key, value])
                return
        self.raise_error(f"attempt to index a {lua_type_name(table)} value")

    def run_call(self, func: Any, args: list[Any], source_line: Optional[int] = None) -> list[Any]:
        return run_generator(self.call(func, args, source_line))

    def call(self, func: Any, args: list[Any], source_line: Optional[int]) -> Generator[Any, list[Any], list[Any]]:
        target = func
        call_args = list(args)
        if not isinstance(target, (LuaFunction, BuiltinFunction)):
            mm = self.get_metamethod(target, "__call")
            if mm is not NIL:
                target = mm
                call_args = [func] + call_args
            else:
                self.raise_error(f"attempt to call a {lua_type_name(func)} value")
        if isinstance(target, BuiltinFunction):
            self.push_frame("[C]", 0, target.name, target.kind, is_c=True)
            try:
                result = target.func(*call_args)
                if isinstance(result, types.GeneratorType):
                    result = yield from result
                if result is None:
                    return []
                if isinstance(result, list):
                    return result
                return [result]
            finally:
                self.pop_frame()
        assert isinstance(target, LuaFunction)
        self.push_frame(target.source_name, target.body.line, target.display_name or "?", "function")
        scope = Scope(self, target.scope.env, target.scope)
        for name, attr in zip(target.body.params, target.body.attrs):
            scope.define(name, NIL, attr)
        if target.body.vararg:
            extra = args[len(target.body.params) :]
        else:
            extra = []
        assigned = adjust_assign(args, len(target.body.params))
        for name, value in zip(target.body.params, assigned):
            scope.set(name, value)
        if target.body.vararg:
            scope.define("...", extra)
        try:
            try:
                yield from self.exec_block(target.body.block, scope)
            except LuaReturn as ret:
                return ret.values
            return []
        finally:
            try:
                yield from scope.close(NIL)
            finally:
                self.pop_frame()

    def exec_chunk(
        self,
        chunk: Chunk,
        env: Optional[LuaTable] = None,
        varargs: Optional[list[Any]] = None,
    ) -> Generator[Any, list[Any], list[Any]]:
        env = env or self.globals
        scope = Scope(self, env)
        scope.define("_ENV", env)
        if varargs is not None:
            scope.define("...", varargs)
        self.push_frame(chunk.source_name, 1, "main chunk", "main chunk")
        try:
            try:
                yield from self.exec_block(chunk.body, scope)
            except LuaReturn as ret:
                return ret.values
            return []
        finally:
            try:
                yield from scope.close(NIL)
            finally:
                self.pop_frame()

    def exec_block(self, block: Block, scope: Scope) -> Generator[Any, list[Any], None]:
        label_map = {
            stmt.label: idx
            for idx, stmt in enumerate(block.statements)
            if isinstance(stmt, LabelStmt)
        }
        pc = 0
        while pc < len(block.statements):
            stmt = block.statements[pc]
            self.set_line(stmt.line)
            try:
                yield from self.exec_stmt(stmt, scope)
            except LuaGoto as gt:
                if gt.label in label_map:
                    pc = label_map[gt.label] + 1
                    continue
                raise
            pc += 1
        if block.returns is not None:
            values = yield from self.eval_explist(block.returns, scope)
            raise LuaReturn(values)

    def exec_stmt(self, stmt: Node, scope: Scope) -> Generator[Any, list[Any], None]:
        if isinstance(stmt, Assign):
            refs = [yield from self.resolve_lvalue(target, scope) for target in stmt.targets]
            values = yield from self.eval_explist(stmt.values, scope)
            values = adjust_assign(values, len(refs))
            for ref, value in zip(refs, values):
                kind = ref[0]
                if kind == "name":
                    scope.set(ref[1], value)
                else:
                    self.table_set(ref[1], ref[2], value)
            return
        if isinstance(stmt, LocalAssign):
            values = yield from self.eval_explist(stmt.values, scope)
            values = adjust_assign(values, len(stmt.names))
            for name, attr, value in zip(stmt.names, stmt.attrs, values):
                scope.define(name, value, attr)
            return
        if isinstance(stmt, LocalFunction):
            cell = scope.define(stmt.name, NIL)
            func = LuaFunction(self, stmt.body, scope, self.current_frame().source_name if self.current_frame() else "stdin", getattr(self, "_current_source_text", ""), stmt.name)
            cell.value = func
            return
        if isinstance(stmt, FunctionAssign):
            func = LuaFunction(self, stmt.body, scope, self.current_frame().source_name if self.current_frame() else "stdin", getattr(self, "_current_source_text", ""), stmt.method_name or stmt.path[-1])
            target: Any = scope.get(stmt.path[0])
            if len(stmt.path) == 1:
                scope.set(stmt.path[0], func)
                return
            for name in stmt.path[1:-1]:
                target = self.table_get(target, name)
            self.table_set(target, stmt.path[-1], func)
            return
        if isinstance(stmt, CallStmt):
            yield from self.eval_expr(stmt.call, scope, multires=False)
            return
        if isinstance(stmt, IfStmt):
            for cond, block in stmt.branches:
                if truthy((yield from self.eval_expr(cond, scope))[0]):
                    inner = Scope(self, scope.env, scope)
                    try:
                        yield from self.exec_block(block, inner)
                    finally:
                        yield from inner.close(NIL)
                    return
            if stmt.else_block is not None:
                inner = Scope(self, scope.env, scope)
                try:
                    yield from self.exec_block(stmt.else_block, inner)
                finally:
                    yield from inner.close(NIL)
            return
        if isinstance(stmt, WhileStmt):
            while truthy((yield from self.eval_expr(stmt.cond, scope))[0]):
                inner = Scope(self, scope.env, scope)
                try:
                    try:
                        yield from self.exec_block(stmt.block, inner)
                    except LuaBreak:
                        return
                finally:
                    yield from inner.close(NIL)
            return
        if isinstance(stmt, RepeatStmt):
            while True:
                inner = Scope(self, scope.env, scope)
                err = NIL
                try:
                    try:
                        yield from self.exec_block(stmt.block, inner)
                    except LuaBreak:
                        return
                except LuaRuntimeError as exc:
                    err = exc.message
                    raise
                finally:
                    yield from inner.close(err)
                if truthy((yield from self.eval_expr(stmt.cond, inner))[0]):
                    return
            return
        if isinstance(stmt, DoStmt):
            inner = Scope(self, scope.env, scope)
            try:
                yield from self.exec_block(stmt.block, inner)
            finally:
                yield from inner.close(NIL)
            return
        if isinstance(stmt, NumericFor):
            start = self.to_number((yield from self.eval_expr(stmt.start, scope))[0])
            stop = self.to_number((yield from self.eval_expr(stmt.stop, scope))[0])
            step = self.to_number((yield from self.eval_expr(stmt.step, scope))[0]) if stmt.step is not None else 1
            value = start
            def cond(v: Any) -> bool:
                return v <= stop if step >= 0 else v >= stop
            while cond(value):
                inner = Scope(self, scope.env, scope)
                inner.define(stmt.name, value, "const")
                try:
                    try:
                        yield from self.exec_block(stmt.block, inner)
                    except LuaBreak:
                        return
                finally:
                    yield from inner.close(NIL)
                value = value + step
            return
        if isinstance(stmt, GenericFor):
            results = yield from self.eval_explist(stmt.values, scope)
            iterator = results[0] if len(results) > 0 else NIL
            state = results[1] if len(results) > 1 else NIL
            control = results[2] if len(results) > 2 else NIL
            while True:
                out = yield from self.call(iterator, [state, control], stmt.line)
                control = out[0] if out else NIL
                if control is NIL:
                    return
                inner = Scope(self, scope.env, scope)
                assigned = adjust_assign(out, len(stmt.names))
                for name, value in zip(stmt.names, assigned):
                    inner.define(name, value, "const")
                try:
                    try:
                        yield from self.exec_block(stmt.block, inner)
                    except LuaBreak:
                        return
                finally:
                    yield from inner.close(NIL)
            return
        if isinstance(stmt, BreakStmt):
            raise LuaBreak()
        if isinstance(stmt, GotoStmt):
            raise LuaGoto(stmt.label)
        if isinstance(stmt, LabelStmt):
            return
        raise NotImplementedError(f"unsupported statement {stmt!r}")

    def resolve_lvalue(self, expr: Expr, scope: Scope) -> Generator[Any, list[Any], tuple[Any, ...]]:
        if isinstance(expr, Name):
            return ("name", expr.id)
        if isinstance(expr, FieldExpr):
            table = (yield from self.eval_expr(expr.table, scope))[0]
            return ("index", table, expr.name)
        if isinstance(expr, IndexExpr):
            table = (yield from self.eval_expr(expr.table, scope))[0]
            key = (yield from self.eval_expr(expr.key, scope))[0]
            return ("index", table, key)
        raise LuaRuntimeError("invalid assignment target", self.snapshot_stack())

    def eval_explist(self, exprs: list[Expr], scope: Scope) -> Generator[Any, list[Any], list[Any]]:
        if not exprs:
            return []
        out: list[Any] = []
        for expr in exprs[:-1]:
            values = yield from self.eval_expr(expr, scope, multires=False)
            out.append(values[0] if values else NIL)
        out.extend((yield from self.eval_expr(exprs[-1], scope, multires=True)))
        return out

    def eval_expr(self, expr: Expr, scope: Scope, multires: bool = False) -> Generator[Any, list[Any], list[Any]]:
        self.set_line(expr.line)
        if isinstance(expr, Literal):
            return [expr.value]
        if isinstance(expr, Name):
            return [scope.get(expr.id)]
        if isinstance(expr, VarArg):
            cell = scope.lookup_cell("...")
            values = cell.value if cell is not None else []
            if multires:
                return list(values)
            return [values[0] if values else NIL]
        if isinstance(expr, ParenExpr):
            values = yield from self.eval_expr(expr.value, scope, multires=False)
            return [values[0] if values else NIL]
        if isinstance(expr, UnaryOp):
            value = (yield from self.eval_expr(expr.value, scope))[0]
            return [self.eval_unary(expr.op, value)]
        if isinstance(expr, BinaryOp):
            if expr.op == "and":
                left = (yield from self.eval_expr(expr.left, scope))[0]
                if not truthy(left):
                    return [left]
                return [((yield from self.eval_expr(expr.right, scope))[0])]
            if expr.op == "or":
                left = (yield from self.eval_expr(expr.left, scope))[0]
                if truthy(left):
                    return [left]
                return [((yield from self.eval_expr(expr.right, scope))[0])]
            left = (yield from self.eval_expr(expr.left, scope))[0]
            right = (yield from self.eval_expr(expr.right, scope))[0]
            return [yield from self.eval_binary(expr.op, left, right)]
        if isinstance(expr, TableConstructor):
            table = LuaTable()
            next_index = 1
            for i, field in enumerate(expr.fields):
                if field.kind == "array":
                    is_last = i == len(expr.fields) - 1
                    values = yield from self.eval_expr(field.value, scope, multires=is_last)
                    for value in values:
                        table.rawset(next_index, value)
                        next_index += 1
                elif field.kind == "name":
                    table.rawset(field.key.value, (yield from self.eval_expr(field.value, scope))[0])  # type: ignore[union-attr]
                else:
                    key = (yield from self.eval_expr(field.key, scope))[0]  # type: ignore[arg-type]
                    value = (yield from self.eval_expr(field.value, scope))[0]
                    table.rawset(key, value)
            return [table]
        if isinstance(expr, FunctionDef):
            frame = self.current_frame()
            source_name = frame.source_name if frame else "stdin"
            return [LuaFunction(self, expr.body, scope, source_name, getattr(self, "_current_source_text", ""), None)]
        if isinstance(expr, IndexExpr):
            table = (yield from self.eval_expr(expr.table, scope))[0]
            key = (yield from self.eval_expr(expr.key, scope))[0]
            return [self.table_get(table, key)]
        if isinstance(expr, FieldExpr):
            table = (yield from self.eval_expr(expr.table, scope))[0]
            return [self.table_get(table, expr.name)]
        if isinstance(expr, CallExpr):
            args = yield from self.eval_explist(expr.args, scope)
            func = (yield from self.eval_expr(expr.func, scope))[0]
            if expr.method is not None:
                selfobj = func
                func = self.table_get(selfobj, expr.method)
                args = [selfobj] + args
            results = yield from self.call(func, args, expr.line)
            if multires:
                return results
            return [results[0] if results else NIL]
        raise NotImplementedError(f"unsupported expr {expr!r}")

    def eval_unary(self, op: str, value: Any) -> Any:
        if op == "-":
            num = self.to_number(value)
            return -num
        if op == "not":
            return not truthy(value)
        if op == "#":
            if isinstance(value, LuaTable):
                mm = self.get_metamethod(value, "__len")
                if mm is not NIL:
                    result = self.run_call(mm, [value])
                    return result[0] if result else NIL
                return value.length()
            if isinstance(value, str):
                return len(value)
            self.raise_error(f"attempt to get length of a {lua_type_name(value)} value")
        if op == "~":
            return int64(~self.to_number(value, integer=True))
        self.raise_error(f"unknown unary op {op}")

    def eval_binary(self, op: str, left: Any, right: Any) -> Generator[Any, list[Any], Any]:
        if op in {"+", "-", "*", "/", "//", "%", "^", "&", "|", "~", "<<", ">>"}:
            return (yield from self.binary_arith(op, left, right))
        if op == "..":
            return (yield from self.binary_concat(left, right))
        if op in {"<", "<=", ">", ">=", "==", "~="}:
            return (yield from self.binary_compare(op, left, right))
        raise NotImplementedError(op)

    def binary_arith(self, op: str, left: Any, right: Any) -> Generator[Any, list[Any], Any]:
        try:
            a = self.to_number(left)
            b = self.to_number(right)
        except LuaRuntimeError:
            mm_name = {
                "+": "__add",
                "-": "__sub",
                "*": "__mul",
                "/": "__div",
                "//": "__idiv",
                "%": "__mod",
                "^": "__pow",
                "&": "__band",
                "|": "__bor",
                "~": "__bxor",
                "<<": "__shl",
                ">>": "__shr",
            }[op]
            mm = self.get_metamethod(left, mm_name)
            if mm is NIL:
                mm = self.get_metamethod(right, mm_name)
            if mm is not NIL:
                result = yield from self.call(mm, [left, right], None)
                return result[0] if result else NIL
            op_name = {
                "+": "add",
                "-": "subtract",
                "*": "multiply",
                "/": "divide",
                "//": "floor divide",
                "%": "mod",
                "^": "pow",
                "&": "bitwise and",
                "|": "bitwise or",
                "~": "bitwise xor",
                "<<": "shift left",
                ">>": "shift right",
            }[op]
            self.raise_error(f"attempt to {op_name} a '{lua_type_name(left)}' with a '{lua_type_name(right)}'")
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            return a / b
        if op == "//":
            return _math.floor(a / b)
        if op == "%":
            return a - _math.floor(a / b) * b
        if op == "^":
            return a ** b
        ia = self.to_number(a, integer=True)
        ib = self.to_number(b, integer=True)
        if op == "&":
            return int64(ia & ib)
        if op == "|":
            return int64(ia | ib)
        if op == "~":
            return int64(ia ^ ib)
        if op == "<<":
            return int64(ia << ib)
        if op == ">>":
            if ia < 0:
                ia &= (1 << 64) - 1
            return int64(ia >> ib)
        raise NotImplementedError(op)

    def binary_concat(self, left: Any, right: Any) -> Generator[Any, list[Any], Any]:
        if isinstance(left, (int, float, str)) and isinstance(right, (int, float, str)):
            return lua_tostring(self, left) + lua_tostring(self, right)
        mm = self.get_metamethod(left, "__concat")
        if mm is NIL:
            mm = self.get_metamethod(right, "__concat")
        if mm is not NIL:
            result = yield from self.call(mm, [left, right], None)
            return result[0] if result else NIL
        self.raise_error(f"attempt to concatenate a '{lua_type_name(left)}' with a '{lua_type_name(right)}'")

    def binary_compare(self, op: str, left: Any, right: Any) -> Generator[Any, list[Any], Any]:
        if op in {"==", "~="}:
            result = yield from self.lua_equal(left, right)
            return result if op == "==" else not result
        if isinstance(left, (int, float)) and isinstance(right, (int, float)):
            a = float(left) if isinstance(left, float) or isinstance(right, float) else left
            b = float(right) if isinstance(left, float) or isinstance(right, float) else right
            return compare_primitive(op, a, b)
        if isinstance(left, str) and isinstance(right, str):
            return compare_primitive(op, left, right)
        self.compare_error(left, right)

    def lua_equal(self, left: Any, right: Any) -> Generator[Any, list[Any], bool]:
        if left is NIL and right is NIL:
            return True
        if type(left) is type(right):
            if isinstance(left, (str, int, float, bool)):
                return left == right
            if left is right:
                return True
        if isinstance(left, (int, float)) and isinstance(right, (int, float)):
            return float(left) == float(right)
        mm = self.get_metamethod(left, "__eq")
        if mm is NIL:
            mm = self.get_metamethod(right, "__eq")
        if mm is not NIL:
            result = yield from self.call(mm, [left, right], None)
            return truthy(result[0] if result else NIL)
        return left is right

    # Base library
    def lib_print(self, *args: Any) -> list[Any]:
        self.stdout.write("\t".join(lua_tostring(self, arg) for arg in args) + "\n")
        self.stdout.flush()
        return []

    def lib_type(self, value: Any = NIL) -> str:
        return lua_type_name(value)

    def lib_tostring(self, value: Any = NIL) -> str:
        return lua_tostring(self, value)

    def lib_tonumber(self, value: Any = NIL, base: Any = NIL) -> Any:
        if base is NIL:
            return lua_tonumber(value)
        return lua_tonumber(value, int(self.to_number(base, integer=True)))

    def lib_assert(self, condition: Any = NIL, *rest: Any) -> list[Any]:
        if truthy(condition):
            return [condition, *rest]
        self.raise_error(rest[0] if rest else "assertion failed!")

    def lib_error(self, message: Any = NIL, level: Any = 1) -> list[Any]:
        level_num = int(self.to_number(level, integer=True)) if level is not NIL else 1
        if level_num != 0 and isinstance(message, str):
            frame = self.current_frame()
            if frame is not None and not frame.is_c:
                message = f"{frame.source_name}:{frame.line}: {message}"
        self.raise_error(message)

    def lib_pcall(self, func: Any, *args: Any) -> Generator[Any, list[Any], list[Any]]:
        try:
            out = yield from self.call(func, list(args), None)
            return [True, *out]
        except LuaRuntimeError as exc:
            return [False, exc.message]

    def lib_xpcall(self, func: Any, msgh: Any) -> Generator[Any, list[Any], list[Any]]:
        try:
            out = yield from self.call(func, [], None)
            return [True, *out]
        except LuaRuntimeError as exc:
            handled = yield from self.call(msgh, [exc.message], None)
            return [False, handled[0] if handled else NIL]

    def lib_warn(self, *args: Any) -> list[Any]:
        if args and isinstance(args[0], str) and args[0] in {"@on", "@off"}:
            self.warning_state = args[0] == "@on"
            return []
        if self.warnings_enabled and self.warning_state:
            self.stderr.write("Lua warning: " + "".join(lua_tostring(self, arg) for arg in args) + "\n")
            self.stderr.flush()
        return []

    def lib_next(self, table: Any, index: Any = NIL) -> list[Any]:
        self.expect_table("next", table)
        keys = list(table.values.keys())
        if index is NIL:
            if not keys:
                return [NIL]
            key = keys[0]
            return [key, table.rawget(key)]
        try:
            pos = keys.index(canonical_key(index)) + 1
        except ValueError:
            self.raise_error("invalid key to 'next'")
        if pos >= len(keys):
            return [NIL]
        key = keys[pos]
        return [key, table.rawget(key)]

    def lib_pairs(self, table: Any) -> Generator[Any, list[Any], list[Any]]:
        mm = self.get_metamethod(table, "__pairs")
        if mm is not NIL:
            return (yield from self.call(mm, [table], None))
        self.expect_table("pairs", table)
        return [self.globals.rawget("next"), table, NIL]

    def lib_ipairs(self, table: Any) -> list[Any]:
        def iterator(state: Any, idx: Any = 0) -> list[Any]:
            i = int(self.to_number(idx, integer=True)) + 1
            value = self.table_get(state, i)
            if value is NIL:
                return [NIL]
            return [i, value]

        return [BuiltinFunction("ipairsaux", iterator), table, 0]

    def lib_rawequal(self, a: Any, b: Any) -> bool:
        return raw_equal(a, b)

    def lib_rawget(self, table: Any, key: Any) -> Any:
        self.expect_table("rawget", table)
        return table.rawget(key)

    def lib_rawset(self, table: Any, key: Any, value: Any) -> LuaTable:
        self.expect_table("rawset", table)
        table.rawset(key, value)
        return table

    def lib_rawlen(self, value: Any) -> int:
        if isinstance(value, LuaTable):
            return value.rawlen()
        if isinstance(value, str):
            return len(value)
        self.raise_error(f"bad argument #1 to 'rawlen' (table or string expected, got {lua_type_name(value)})")

    def lib_setmetatable(self, table: Any, mt: Any) -> LuaTable:
        self.expect_table("setmetatable", table)
        if table.metatable is not None and table.metatable.rawget("__metatable") is not NIL:
            self.raise_error("cannot change a protected metatable")
        if mt is not NIL and not isinstance(mt, LuaTable):
            self.arg_error("setmetatable", 2, "nil or table expected", mt)
        table.metatable = None if mt is NIL else mt
        return table

    def lib_getmetatable(self, value: Any) -> Any:
        mt = self.get_metatable(value)
        if mt is None:
            return NIL
        protected = mt.rawget("__metatable")
        return protected if protected is not NIL else mt

    def lib_select(self, index: Any, *args: Any) -> Any:
        if index == "#":
            return len(args)
        n = int(self.to_number(index, integer=True))
        if n < 0:
            n = len(args) + n + 1
        n = max(1, n)
        return list(args[n - 1 :])

    def lib_dofile(self, filename: Any = NIL) -> Generator[Any, list[Any], list[Any]]:
        path = filename if filename is not NIL else None
        if path is None:
            text = self.stdin.read()
            chunk = compile_chunk("stdin", text)
            return (yield from self.exec_chunk(chunk))
        text = pathlib.Path(str(path)).read_text()
        chunk = compile_chunk(str(path), text)
        return (yield from self.exec_chunk(chunk))

    def lib_load(self, chunk: Any, chunkname: Any = "=(load)", mode: Any = "bt", env: Any = NIL) -> list[Any]:
        try:
            source = str(chunkname)
            text, binary = self.read_load_chunk(chunk)
            mode_s = str(mode)
            if binary and "b" not in mode_s:
                return [NIL, f"attempt to load a binary chunk (mode is '{mode_s}')"]
            if (not binary) and "t" not in mode_s:
                return [NIL, f"attempt to load a text chunk (mode is '{mode_s}')"]
            if binary:
                text = decode_binary_chunk(text)
            compiled = compile_chunk(source, text)
            env_table = self.globals if env is NIL else env
            if not isinstance(env_table, LuaTable):
                self.arg_error("load", 4, "table expected", env_table)
            def loader(*_args: Any) -> Generator[Any, list[Any], list[Any]]:
                return (yield from self.exec_chunk(compiled, env_table))
            func = BuiltinFunction(source, loader)
            return [func]
        except (LuaParseError, OSError, LuaRuntimeError) as exc:
            return [NIL, str(exc)]

    def lib_loadfile(self, filename: Any = NIL, mode: Any = "bt", env: Any = NIL) -> list[Any]:
        try:
            if filename is NIL:
                return [NIL, "filename expected"]
            path = pathlib.Path(str(filename))
            if not path.exists():
                return [NIL, f"cannot open {path}: No such file"]
            data = path.read_text(errors="ignore")
            return self.lib_load(data, str(path), mode, env)
        except OSError as exc:
            return [NIL, f"cannot open {filename}: {exc.strerror}"]

    def lib_require(self, name: Any) -> Generator[Any, list[Any], list[Any]]:
        module_name = str(name)
        loaded = self.package.rawget("loaded")
        cached = loaded.rawget(module_name)
        if cached is not NIL:
            return [cached]
        searchers = self.package.rawget("searchers")
        errors: list[str] = []
        for i in range(1, searchers.length() + 1):
            searcher = searchers.rawget(i)
            if searcher is NIL:
                continue
            result = yield from self.call(searcher, [module_name], None)
            loader = result[0] if result else NIL
            if isinstance(loader, (BuiltinFunction, LuaFunction)):
                args = [module_name, *(result[1:] if len(result) > 1 else [])]
                out = yield from self.call(loader, args, None)
                value = out[0] if out else True
                loaded.rawset(module_name, value if value is not NIL else True)
                return [loaded.rawget(module_name)]
            if loader is not NIL:
                errors.append(lua_tostring(self, loader))
        self.raise_error(f"module '{module_name}' not found:\n" + "\n".join(errors))

    def lib_collectgarbage(self, *_args: Any) -> int:
        return 0

    # Table library
    def expect_table(self, fname: str, value: Any) -> LuaTable:
        if not isinstance(value, LuaTable):
            self.arg_error(fname, 1, "table expected", value)
        return value

    def table_concat(self, table: Any, sep: Any = "", i: Any = 1, j: Any = NIL) -> str:
        table = self.expect_table("concat", table)
        start = int(self.to_number(i, integer=True))
        stop = table.length() if j is NIL else int(self.to_number(j, integer=True))
        parts = []
        for idx in range(start, stop + 1):
            parts.append(lua_tostring(self, table.rawget(idx)))
        return str(sep).join(parts)

    def table_insert(self, table: Any, pos: Any = NIL, value: Any = NIL) -> list[Any]:
        table = self.expect_table("insert", table)
        length = table.length()
        if value is NIL:
            value = pos
            pos_num = length + 1
        else:
            pos_num = int(self.to_number(pos, integer=True))
        for idx in range(length, pos_num - 1, -1):
            table.rawset(idx + 1, table.rawget(idx))
        table.rawset(pos_num, value)
        return []

    def table_remove(self, table: Any, pos: Any = NIL) -> Any:
        table = self.expect_table("remove", table)
        length = table.length()
        pos_num = length if pos is NIL else int(self.to_number(pos, integer=True))
        value = table.rawget(pos_num)
        for idx in range(pos_num, length):
            table.rawset(idx, table.rawget(idx + 1))
        table.rawset(length, NIL)
        return value

    def table_move(self, a1: Any, f: Any, e: Any, t: Any, a2: Any = NIL) -> Any:
        src = self.expect_table("move", a1)
        dst = src if a2 is NIL else self.expect_table("move", a2)
        f_i = int(self.to_number(f, integer=True))
        e_i = int(self.to_number(e, integer=True))
        t_i = int(self.to_number(t, integer=True))
        values = [src.rawget(i) for i in range(f_i, e_i + 1)]
        for offset, value in enumerate(values):
            dst.rawset(t_i + offset, value)
        return dst

    def table_pack(self, *args: Any) -> LuaTable:
        table = LuaTable()
        for i, arg in enumerate(args, start=1):
            table.rawset(i, arg)
        table.rawset("n", len(args))
        return table

    def table_unpack(self, table: Any, i: Any = 1, j: Any = NIL) -> list[Any]:
        table = self.expect_table("unpack", table)
        start = int(self.to_number(i, integer=True))
        stop = table.length() if j is NIL else int(self.to_number(j, integer=True))
        return [self.table_get(table, idx) for idx in range(start, stop + 1)]

    def table_sort(self, table: Any, comp: Any = NIL) -> Generator[Any, list[Any], list[Any]]:
        table = self.expect_table("sort", table)
        values = [table.rawget(i) for i in range(1, table.length() + 1)]
        if comp is NIL:
            values.sort(key=functools.cmp_to_key(lambda a, b: -1 if compare_primitive("<", a, b) else (1 if compare_primitive(">", a, b) else 0)))
        else:
            def cmp(a: Any, b: Any) -> int:
                result = self.run_call(comp, [a, b])
                return -1 if truthy(result[0] if result else NIL) else 1
            values.sort(key=functools.cmp_to_key(cmp))
        for idx, value in enumerate(values, start=1):
            table.rawset(idx, value)
        return []

    def table_create(self, narr: Any, nrec: Any = 0) -> LuaTable:
        if lua_tonumber(narr) is None:
            self.arg_error("create", 1, "number expected", narr)
        if lua_tonumber(nrec) is None:
            self.arg_error("create", 2, "number expected", nrec)
        return LuaTable()

