    def math_modf(self, value: Any) -> list[Any]:
        num = self.to_number(value)
        frac, integ = _math.modf(num)
        return [int(integ) if float(integ).is_integer() else integ, frac]

    def math_random(self, m: Any = NIL, n: Any = NIL) -> Any:
        if m is NIL:
            return self.random.random()
        if n is NIL:
            hi = int(self.to_number(m, integer=True))
            return self.random.randint(1, hi)
        lo = int(self.to_number(m, integer=True))
        hi = int(self.to_number(n, integer=True))
        return self.random.randint(lo, hi)

    def math_randomseed(self, x: Any = NIL, y: Any = NIL) -> list[Any]:
        seed = int(self.to_number(x if x is not NIL else time.time(), integer=True))
        if y is not NIL:
            seed ^= int(self.to_number(y, integer=True))
        self.random.seed(seed)
        return [seed, 0]

    def math_tointeger(self, value: Any) -> Any:
        if isinstance(value, int):
            return value
        if isinstance(value, float) and value.is_integer():
            return int(value)
        if isinstance(value, str):
            num = lua_tonumber(value)
            if isinstance(num, int):
                return num
            if isinstance(num, float) and num.is_integer():
                return int(num)
        return NIL

    def math_type(self, value: Any = NIL) -> Any:
        if isinstance(value, int):
            return "integer"
        if isinstance(value, float):
            return "float"
        return NIL

    def math_ult(self, m: Any, n: Any) -> bool:
        a = int(self.to_number(m, integer=True)) & ((1 << 64) - 1)
        b = int(self.to_number(n, integer=True)) & ((1 << 64) - 1)
        return a < b

    # String library
    def lua_pattern_to_regex(self, pattern: str) -> str:
        out = []
        i = 0
        classes = {
            "a": "A-Za-z",
            "d": "0-9",
            "l": "a-z",
            "u": "A-Z",
            "w": "A-Za-z0-9_",
            "s": r"\s",
            "x": "0-9A-Fa-f",
            "p": r"""!"#$%&'()*+,\-./:;<=>?@\[\\\]^_`{|}~""",
            "g": r"\S",
            "c": r"\x00-\x1F\x7F",
            "z": r"\x00",
        }
        while i < len(pattern):
            ch = pattern[i]
            if ch == "%":
                i += 1
                if i >= len(pattern):
                    out.append("%")
                    break
                code = pattern[i]
                if code in classes:
                    out.append(f"[{classes[code]}]")
                elif code.lower() in classes:
                    out.append(f"[^{classes[code.lower()]}]")
                else:
                    out.append(re.escape(code))
            elif ch == "-":
                out.append("*?")
            elif ch in ".^$*+?{}[]()|":
                if ch == ".":
                    out.append(".")
                else:
                    out.append("\\" + ch)
            else:
                out.append(re.escape(ch))
            i += 1
        return "".join(out)

    def string_byte(self, s: Any, i: Any = 1, j: Any = NIL) -> list[Any]:
        text = str(s)
        start = lua_index(len(text), int(self.to_number(i, integer=True)))
        stop = start if j is NIL else lua_index(len(text), int(self.to_number(j, integer=True)))
        out = []
        for idx in range(start, stop + 1):
            if 1 <= idx <= len(text):
                out.append(ord(text[idx - 1]))
        return out

    def string_char(self, *args: Any) -> str:
        return "".join(chr(int(self.to_number(arg, integer=True)) & 0xFF) for arg in args)

    def string_dump(self, func: Any, strip: Any = NIL) -> str:
        if isinstance(func, LuaFunction) and func.dump_source:
            payload = func.dump_source
        else:
            payload = "return function(...) end"
        return BINARY_CHUNK_PREFIX + payload

    def string_find(self, s: Any, pattern: Any, init: Any = 1, plain: Any = False) -> list[Any]:
        text = str(s)
        pat = str(pattern)
        start = max(0, lua_index(len(text), int(self.to_number(init, integer=True))) - 1)
        if truthy(plain):
            pos = text.find(pat, start)
            if pos < 0:
                return [NIL]
            return [pos + 1, pos + len(pat)]
        regex = re.compile(self.lua_pattern_to_regex(pat))
        match = regex.search(text, start)
        if not match:
            return [NIL]
        return [match.start() + 1, match.end(), *match.groups()]

    def string_format(self, fmt: Any, *args: Any) -> str:
        text = str(fmt)
        py_args = tuple(lua_tostring(self, arg) if "%s" in text else python_format_arg(arg) for arg in args)
        try:
            return text % py_args
        except Exception:
            out = text
            for arg in args:
                out = out.replace("%s", lua_tostring(self, arg), 1)
            return out.replace("%%", "%")

    def string_gmatch(self, s: Any, pattern: Any) -> BuiltinFunction:
        text = str(s)
        regex = re.compile(self.lua_pattern_to_regex(str(pattern)))
        iterator = iter(regex.finditer(text))
        def gen(_state: Any = NIL, _ctrl: Any = NIL) -> list[Any]:
            try:
                match = next(iterator)
            except StopIteration:
                return [NIL]
            groups = match.groups()
            if groups:
                return list(groups)
            return [match.group(0)]
        return BuiltinFunction("gmatchaux", gen)

    def string_gsub(self, s: Any, pattern: Any, repl: Any, n: Any = NIL) -> list[Any]:
        text = str(s)
        regex = re.compile(self.lua_pattern_to_regex(str(pattern)))
        limit = 0 if n is NIL else int(self.to_number(n, integer=True))
        count = 0
        def replace(match: re.Match[str]) -> str:
            nonlocal count
            if limit and count >= limit:
                return match.group(0)
            count += 1
            if isinstance(repl, str):
                result = repl
                for idx, group in enumerate(match.groups(), start=1):
                    result = result.replace(f"%{idx}", group or "")
                return result
            if isinstance(repl, LuaTable):
                key = match.group(1) if match.groups() else match.group(0)
                value = self.table_get(repl, key)
                return match.group(0) if value is NIL else lua_tostring(self, value)
            out = self.run_call(repl, list(match.groups() or [match.group(0)]))
            return lua_tostring(self, out[0] if out else "")
        result = regex.sub(replace, text, count=limit or 0)
        return [result, count]

    def string_len(self, s: Any) -> int:
        return len(str(s))

    def string_lower(self, s: Any) -> str:
        return str(s).lower()

    def string_match(self, s: Any, pattern: Any, init: Any = 1) -> list[Any]:
        out = self.string_find(s, pattern, init, False)
        if out and out[0] is not NIL and len(out) > 2:
            return out[2:]
        if out and out[0] is not NIL:
            text = str(s)
            start = int(out[0]) - 1
            stop = int(out[1])
            return [text[start:stop]]
        return [NIL]

    def string_pack(self, fmt: Any, *args: Any) -> str:
        data = lua_pack(str(fmt), args)
        return data.decode("latin1")

    def string_packsize(self, fmt: Any) -> int:
        return lua_packsize(str(fmt))

    def string_rep(self, s: Any, n: Any, sep: Any = "") -> str:
        count = int(self.to_number(n, integer=True))
        items = [str(s)] * count
        return str(sep).join(items)

    def string_reverse(self, s: Any) -> str:
        return str(s)[::-1]

    def string_sub(self, s: Any, i: Any, j: Any = NIL) -> str:
        text = str(s)
        start = lua_index(len(text), int(self.to_number(i, integer=True)))
        stop = len(text) if j is NIL else lua_index(len(text), int(self.to_number(j, integer=True)))
        if start > stop:
            return ""
        return text[max(start - 1, 0) : max(stop, 0)]

    def string_unpack(self, fmt: Any, s: Any, pos: Any = 1) -> list[Any]:
        values, next_pos = lua_unpack(str(fmt), str(s).encode("latin1"), int(self.to_number(pos, integer=True)))
        return [*values, next_pos]

    def string_upper(self, s: Any) -> str:
        return str(s).upper()

    # Package library
    def package_searchpath(self, name: Any, path: Any, sep: Any = ".", rep: Any = os.sep) -> list[Any]:
        module = str(name).replace(str(sep), str(rep))
        for template in str(path).split(";"):
            candidate = template.replace("?", module)
            if os.path.exists(candidate):
                return [candidate]
        return [NIL, f"\n\tno file '{module}'"]

    def package_preload_searcher(self, name: Any) -> list[Any]:
        preload = self.package.rawget("preload")
        loader = preload.rawget(str(name))
        if loader is NIL:
            return ["\n\tno field package.preload['" + str(name) + "']"]
        return [loader]

    def package_lua_searcher(self, name: Any) -> list[Any]:
        found = self.package_searchpath(name, self.package.rawget("path"))
        if found[0] is NIL:
            return found
        path = found[0]
        try:
            text = pathlib.Path(str(path)).read_text()
        except OSError:
            return [f"\n\tno file '{path}'"]
        chunk = compile_chunk(str(path), text)
        def loader(_modname: Any = NIL, _path: Any = NIL) -> Generator[Any, list[Any], list[Any]]:
            return (yield from self.exec_chunk(chunk))
        return [BuiltinFunction(f"loader:{name}", loader), path]

    def package_c_searcher(self, name: Any) -> list[Any]:
        return [f"\n\tno file '{name}.so'"]

    def package_croot_searcher(self, name: Any) -> list[Any]:
        return [f"\n\tno module '{name}' in file '{name}.so'"]

    # Coroutine library
    def coroutine_create(self, func: Any) -> LuaThread:
        if not isinstance(func, (LuaFunction, BuiltinFunction)):
            self.arg_error("create", 1, "function expected", func)
        return LuaThread(self, func, self.globals)

    def coroutine_resume(self, thread: Any, *args: Any) -> list[Any]:
        if not isinstance(thread, LuaThread):
            self.arg_error("resume", 1, "thread expected", thread)
        if thread.dead or thread.status == "dead":
            return [False, "cannot resume dead coroutine"]
        if thread.status == "running":
            return [False, "cannot resume running coroutine"]
        prev = self.current_thread
        self.current_thread = thread
        try:
            thread.status = "running"
            if thread.generator is None:
                thread.generator = self.call(thread.func, list(args), None)
                try:
                    yielded = next(thread.generator)
                except StopIteration as stop:
                    thread.dead = True
                    thread.status = "dead"
                    return [True, *(stop.value or [])]
            else:
                try:
                    yielded = thread.generator.send(list(args))
                except StopIteration as stop:
                    thread.dead = True
                    thread.status = "dead"
                    return [True, *(stop.value or [])]
            if isinstance(yielded, CoroutineYield):
                thread.status = "suspended"
                return [True, *yielded.values]
            raise RuntimeError("unexpected coroutine yield")
        except LuaRuntimeError as exc:
            thread.dead = True
            thread.status = "dead"
            return [False, exc.message]
        finally:
            self.current_thread = prev

    def coroutine_running(self) -> list[Any]:
        return [self.current_thread, self.current_thread is self.main_thread]

    def coroutine_status(self, thread: Any) -> str:
        if not isinstance(thread, LuaThread):
            self.arg_error("status", 1, "thread expected", thread)
        return "dead" if thread.dead or thread.status == "dead" else thread.status

    def coroutine_wrap(self, func: Any) -> BuiltinFunction:
        thread = self.coroutine_create(func)
        def wrapped(*args: Any) -> list[Any]:
            out = self.coroutine_resume(thread, *args)
            if not truthy(out[0]):
                self.raise_error(out[1] if len(out) > 1 else NIL)
            return out[1:]
        return BuiltinFunction("wrapped", wrapped)

    def coroutine_yield(self, *args: Any) -> Generator[Any, list[Any], list[Any]]:
        if self.current_thread is self.main_thread:
            self.raise_error("attempt to yield from outside a coroutine")
        received = yield CoroutineYield(list(args))
        return received

    def coroutine_close(self, thread: Any) -> bool:
        if not isinstance(thread, LuaThread):
            self.arg_error("close", 1, "thread expected", thread)
        thread.dead = True
        thread.status = "dead"
        thread.generator = None
        return True

    # IO library
    def io_open(self, filename: Any, mode: Any = "r") -> Any:
        try:
            return open(str(filename), str(mode))
        except OSError as exc:
            return [NIL, exc.strerror, exc.errno]

    def io_lines(self, filename: Any = NIL) -> BuiltinFunction:
        if filename is NIL:
            fh = self.stdin
        else:
            fh = open(str(filename), "r")
        def iterator() -> Any:
            line = fh.readline()
            if line == "":
                return [NIL]
            return [line.rstrip("\n")]
        return BuiltinFunction("lines", lambda _s=NIL, _c=NIL: iterator())

    def io_read(self, *formats: Any) -> Any:
        data = self.stdin.readline()
        return data.rstrip("\n") if data != "" else NIL

    def io_write(self, *args: Any) -> list[Any]:
        self.stdout.write("".join(lua_tostring(self, arg) for arg in args))
        self.stdout.flush()
        return [True]

    def io_flush(self) -> bool:
        self.stdout.flush()
        return True

    # OS library
    def os_clock(self) -> float:
        return time.process_time()

    def os_date(self, fmt: Any = "%c", when: Any = NIL) -> Any:
        ts = time.time() if when is NIL else float(self.to_number(when))
        dt = _dt.datetime.fromtimestamp(ts)
        if fmt == "*t":
            table = LuaTable()
            table.rawset("year", dt.year)
            table.rawset("month", dt.month)
            table.rawset("day", dt.day)
            table.rawset("hour", dt.hour)
            table.rawset("min", dt.minute)
            table.rawset("sec", dt.second)
            table.rawset("wday", dt.isoweekday() % 7 + 1)
            table.rawset("yday", dt.timetuple().tm_yday)
            return table
        return dt.strftime(str(fmt))

    def os_difftime(self, t2: Any, t1: Any = 0) -> float:
        return float(self.to_number(t2) - self.to_number(t1))

    def os_execute(self, command: Any = NIL) -> list[Any]:
        if command is NIL:
            return [True]
        status = os.system(str(command))
        return [status == 0, "exit", status]

    def os_exit(self, code: Any = 0, close: Any = False) -> list[Any]:
        if code is True:
            raise LuaExit(0)
        if code is False:
            raise LuaExit(1)
        raise LuaExit(int(self.to_number(code, integer=True)))

    def os_getenv(self, name: Any) -> Any:
        value = os.getenv(str(name))
        return value if value is not None else NIL

    def os_remove(self, path: Any) -> list[Any]:
        try:
            os.remove(str(path))
            return [True]
        except OSError as exc:
            return [NIL, exc.strerror, exc.errno]

    def os_rename(self, old: Any, new: Any) -> list[Any]:
        try:
            os.rename(str(old), str(new))
            return [True]
        except OSError as exc:
            return [NIL, exc.strerror, exc.errno]

    def os_time(self, table: Any = NIL) -> int:
        if table is NIL:
            return int(time.time())
        if not isinstance(table, LuaTable):
            self.arg_error("time", 1, "table expected", table)
        dt = _dt.datetime(
            int(self.table_get(table, "year")),
            int(self.table_get(table, "month")),
            int(self.table_get(table, "day")),
            int(self.table_get(table, "hour") if self.table_get(table, "hour") is not NIL else 12),
            int(self.table_get(table, "min") if self.table_get(table, "min") is not NIL else 0),
            int(self.table_get(table, "sec") if self.table_get(table, "sec") is not NIL else 0),
        )
        return int(dt.timestamp())

    def os_tmpname(self) -> str:
        import tempfile
        fd, path = tempfile.mkstemp()
        os.close(fd)
        return path

    # Debug library
    def debug_traceback(self, message: Any = NIL, level: Any = 1) -> str:
        text = "" if message is NIL else lua_tostring(self, message) + "\n"
        text += "stack traceback:"
        for frame in reversed(self.call_stack):
            if frame.is_c:
                text += f"\n\t[C]: in {frame.kind} '{frame.name}'"
            else:
                text += f"\n\t{frame.source_name}:{frame.line}: in {frame.kind}"
        return text

    # UTF-8 library
    def utf8_char(self, *codes: Any) -> str:
        return "".join(chr(int(self.to_number(code, integer=True))) for code in codes)

    def utf8_codepoint(self, s: Any, i: Any = 1, j: Any = NIL) -> list[Any]:
        text = str(s)
        start = lua_index(len(text), int(self.to_number(i, integer=True)))
        stop = start if j is NIL else lua_index(len(text), int(self.to_number(j, integer=True)))
        return [ord(ch) for ch in text[start - 1 : stop]]

    def utf8_codes(self, s: Any) -> list[Any]:
        text = str(s)
        index = 0
        def iterator(_state: Any = NIL, _ctrl: Any = NIL) -> list[Any]:
            nonlocal index
            if index >= len(text):
                return [NIL]
            index += 1
            return [index, ord(text[index - 1])]
        return [BuiltinFunction("utf8codes", iterator), NIL, NIL]

    def utf8_len(self, s: Any, i: Any = 1, j: Any = NIL) -> Any:
        text = str(s)
        start = lua_index(len(text), int(self.to_number(i, integer=True)))
        stop = len(text) if j is NIL else lua_index(len(text), int(self.to_number(j, integer=True)))
        return len(text[start - 1 : stop])

    def utf8_offset(self, s: Any, n: Any, i: Any = NIL) -> Any:
        text = str(s)
        idx = 1 if i is NIL else lua_index(len(text), int(self.to_number(i, integer=True)))
        return idx + int(self.to_number(n, integer=True)) - 1

    # Helpers for load
    def read_load_chunk(self, chunk: Any) -> tuple[str, bool]:
        if isinstance(chunk, (LuaFunction, BuiltinFunction)):
            pieces = []
