def raw_equal(a: Any, b: Any) -> bool:
    if a is NIL and b is NIL:
        return True
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return float(a) == float(b)
    return a is b if isinstance(a, (LuaTable, LuaFunction, BuiltinFunction, LuaThread)) else a == b


def compare_primitive(op: str, a: Any, b: Any) -> bool:
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
