def lua_type_name(value: Any) -> str:
    if value is NIL:
        return "nil"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, LuaTable):
        return "table"
    if isinstance(value, (LuaFunction, BuiltinFunction)):
        return "function"
    if isinstance(value, LuaThread):
        return "thread"
    if value is None:
        return "nil"
    return type(value).__name__


def lua_tostring(runtime: Optional[Runtime], value: Any) -> str:
    if value is NIL:
        return "nil"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if _math.isnan(value):
            return "-nan"
        if _math.isinf(value):
            return "inf" if value > 0 else "-inf"
        text = format(value, ".14g")
        if "e" in text and "e+" not in text and "e-" not in text:
            text = text.replace("e", "e+")
        if "." not in text and "e" not in text and "E" not in text:
            text += ".0"
        if value == 0.0 and _math.copysign(1.0, value) < 0:
            return "-0.0"
        return text
    if isinstance(value, str):
        return value
    if runtime is not None:
        mm = runtime.get_metamethod(value, "__tostring")
        if mm is not NIL:
            result = runtime.run_call(mm, [value])
            return lua_tostring(runtime, result[0] if result else NIL)
    if isinstance(value, LuaTable):
        return f"table: 0x{id(value):x}"
    if isinstance(value, (LuaFunction, BuiltinFunction)):
        return f"function: 0x{id(value):x}"
    if isinstance(value, LuaThread):
        return f"thread: 0x{id(value):x}"
    return str(value)


def lua_tonumber(value: Any, base: Optional[int] = None) -> Any:
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, bool) or value is NIL:
        return None
    if not isinstance(value, str):
        return None
    text = value.strip()
    try:
        if base is not None:
            if not (2 <= base <= 36):
                return None
            return int(text, base)
        if re.fullmatch(r"[+\-]?0[xX][0-9A-Fa-f]+", text):
            return int(text, 16)
        if re.fullmatch(r"[+\-]?0[xX](?:[0-9A-Fa-f]+(?:\.[0-9A-Fa-f]*)?|\.[0-9A-Fa-f]+)[pP][+\-]?[0-9]+", text):
            return float.fromhex(text)
        if re.fullmatch(r"[+\-]?[0-9]+", text):
            return int(text, 10)
        return float(text)
    except Exception:
        return None


def lua_index(length: int, index: int) -> int:
    if index < 0:
