def compile_chunk(source_name: str, text: str) -> Chunk:
    parser = Parser(source_name, text)
    chunk = parser.parse()
    return chunk


def run_generator(gen: Generator[Any, list[Any], list[Any]]) -> list[Any]:
    try:
        yielded = next(gen)
    except StopIteration as stop:
        return stop.value or []
    if isinstance(yielded, CoroutineYield):
        raise LuaRuntimeError("attempt to yield from outside a coroutine")
    raise RuntimeError(f"unexpected generator yield {yielded!r}")


