    if not text.startswith(BINARY_CHUNK_PREFIX):
        raise LuaRuntimeError("binary chunk mismatch")
    return text[len(BINARY_CHUNK_PREFIX) :]


def lua_pack_tokens(fmt: str) -> list[tuple[str, Any]]:
    tokens: list[tuple[str, Any]] = []
    i = 0
    endian = "="
    while i < len(fmt):
        ch = fmt[i]
        if ch.isspace():
            i += 1
            continue
        if ch in "<>!=":
            endian = ch
            tokens.append(("endian", ch))
            i += 1
            continue
        if ch in {"b", "B", "h", "H", "l", "L", "j", "J", "T", "f", "d", "n", "i", "I", "c", "s", "z", "x", "X"}:
            j = i + 1
            while j < len(fmt) and fmt[j].isdigit():
                j += 1
            size = fmt[i + 1 : j]
            tokens.append((ch, int(size) if size else None))
            i = j
            continue
        raise LuaRuntimeError(f"invalid format option '{ch}'")
    return tokens


def lua_packsize(fmt: str) -> int:
    tokens = lua_pack_tokens(fmt)
    size = 0
    for kind, arg in tokens:
        if kind == "endian":
            continue
        if kind == "x":
            size += 1
        elif kind == "c":
            size += arg or 0
        elif kind in {"b", "B"}:
            size += 1
        elif kind in {"h", "H"}:
            size += 2
        elif kind in {"l", "L", "f", "i", "I"}:
            size += arg or 4
        elif kind in {"j", "J", "d", "n", "T"}:
            size += arg or 8
        elif kind in {"s", "z", "X"}:
            raise LuaRuntimeError("variable-length format")
    return size


def lua_pack(fmt: str, args: tuple[Any, ...]) -> bytes:
    tokens = lua_pack_tokens(fmt)
    endian = "="
    out = bytearray()
    idx = 0
    for kind, arg in tokens:
        if kind == "endian":
            endian = arg
            continue
        if kind == "x":
            out.append(0)
            continue
        if idx >= len(args):
            raise LuaRuntimeError("bad argument to 'pack'")
        value = args[idx]
        idx += 1
        prefix = {"<": "<", ">": ">", "=": "=", "!": "=", " ": "="}.get(endian, "=")
        if kind == "c":
            data = str(value).encode("latin1")
            width = arg or 0
            if len(data) != width:
                data = data[:width].ljust(width, b"\x00")
            out.extend(data)
        elif kind in {"b", "B", "h", "H"}:
            code = {"b": "b", "B": "B", "h": "h", "H": "H"}[kind]
            out.extend(struct.pack(prefix + code, int(value)))
        elif kind in {"i", "I"}:
            width = arg or 4
            signed = kind == "i"
            out.extend(int(value).to_bytes(width, "little" if prefix == "<" else "big", signed=signed))
        elif kind == "f":
            out.extend(struct.pack(prefix + "f", float(value)))
        elif kind in {"d", "n"}:
            out.extend(struct.pack(prefix + "d", float(value)))
        elif kind == "z":
            out.extend(str(value).encode("latin1") + b"\x00")
        elif kind == "s":
            width = arg or 8
            data = str(value).encode("latin1")
            out.extend(len(data).to_bytes(width, "little" if prefix == "<" else "big"))
            out.extend(data)
        else:
            raise LuaRuntimeError(f"unsupported pack option '{kind}'")
    return bytes(out)


def lua_unpack(fmt: str, data: bytes, pos: int = 1) -> tuple[list[Any], int]:
    tokens = lua_pack_tokens(fmt)
    endian = "="
    idx = pos - 1
    out: list[Any] = []
    for kind, arg in tokens:
        if kind == "endian":
            endian = arg
            continue
        prefix = {"<": "<", ">": ">", "=": "=", "!": "=", " ": "="}.get(endian, "=")
        if kind == "x":
            idx += 1
        elif kind == "c":
            width = arg or 0
            out.append(data[idx : idx + width].decode("latin1"))
            idx += width
        elif kind in {"b", "B", "h", "H"}:
            code = {"b": "b", "B": "B", "h": "h", "H": "H"}[kind]
            size = struct.calcsize(code)
            out.append(struct.unpack(prefix + code, data[idx : idx + size])[0])
            idx += size
        elif kind in {"i", "I"}:
            width = arg or 4
            out.append(int.from_bytes(data[idx : idx + width], "little" if prefix == "<" else "big", signed=kind == "i"))
            idx += width
        elif kind == "f":
            out.append(struct.unpack(prefix + "f", data[idx : idx + 4])[0])
            idx += 4
        elif kind in {"d", "n"}:
            out.append(struct.unpack(prefix + "d", data[idx : idx + 8])[0])
            idx += 8
        elif kind == "z":
            end = data.index(0, idx)
            out.append(data[idx:end].decode("latin1"))
            idx = end + 1
        elif kind == "s":
            width = arg or 8
            length = int.from_bytes(data[idx : idx + width], "little" if prefix == "<" else "big")
            idx += width
            out.append(data[idx : idx + length].decode("latin1"))
            idx += length
        else:
            raise LuaRuntimeError(f"unsupported unpack option '{kind}'")
    return out, idx + 1


def format_runtime_error(argv0: str, err: LuaRuntimeError) -> str:
    message = lua_tostring(None, err.message)
    lines = [f"{argv0}: {message}"]
    if err.stack:
        lines.append("stack traceback:")
        for frame in reversed(err.stack):
            if frame.is_c:
                lines.append(f"\t[C]: in {frame.kind} '{frame.name}'")
            else:
                label = frame.kind
                if label == "main chunk":
                    lines.append(f"\t{frame.source_name}:{frame.line}: in main chunk")
                else:
                    name = f" '{frame.name}'" if frame.name and frame.name != "?" else ""
                    lines.append(f"\t{frame.source_name}:{frame.line}: in {label}{name}")
        lines.append("\t[C]: in ?")
    return "\n".join(lines)


def usage(argv0: str, bad: Optional[str] = None) -> str:
    lines = []
    if bad is not None:
        lines.append(f"{argv0}: {bad}")
    lines.extend(
        [
            f"usage: {argv0} [options] [script [args]]",
            "Available options are:",
            "  -e stat   execute string 'stat'",
            "  -i        enter interactive mode after executing 'script'",
            "  -l mod    require library 'mod' into global 'mod'",
            "  -l g=mod  require library 'mod' into global 'g'",
            "  -v        show version information",
            "  -E        ignore environment variables",
            "  -W        turn warnings on",
            "  --        stop handling options",
            "  -         stop handling options and execute stdin",
        ]
    )
    return "\n".join(lines)


def set_arg_table(runtime: Runtime, mapping: dict[int, Any]) -> None:
    table = LuaTable()
    for key, value in mapping.items():
        table.rawset(key, value)
    runtime.globals.rawset("arg", table)


def build_arg_table(argv0: str, processed: list[str], script: Optional[str], script_args: list[str]) -> dict[int, Any]:
    mapping: dict[int, Any] = {}
    if script is None:
        mapping[0] = argv0
        for idx, token in enumerate(processed, start=1):
            mapping[idx] = token
        return mapping
    negatives = [argv0] + processed
    start = -len(negatives)
    for idx, token in enumerate(negatives):
        mapping[start + idx] = token
    mapping[0] = script
    for idx, token in enumerate(script_args, start=1):
        mapping[idx] = token
    return mapping


def compile_for_repl(source_name: str, text: str, expr_mode: bool = False) -> Chunk:
    if expr_mode:
        text = "return " + text
    return compile_chunk(source_name, text)


def run_repl(runtime: Runtime) -> int:
    banner_printed = False
    sys.stdout.write(VERSION_BANNER + "\n")
    sys.stdout.flush()
    banner_printed = True
    buffer: list[str] = []
    prompt = "> "
    while True:
        try:
            line = input(prompt)
        except EOFError:
            if not buffer:
                if banner_printed:
                    sys.stdout.flush()
                return 0
            line = ""
        buffer.append(line)
        source = "\n".join(buffer)
        chunk: Optional[Chunk] = None
        expr_mode = False
        try:
            try:
                chunk = compile_for_repl("stdin", source, expr_mode=True)
                expr_mode = True
            except LuaParseError as expr_err:
                if expr_err.incomplete:
                    prompt = ">> "
                    continue
                chunk = compile_for_repl("stdin", source, expr_mode=False)
        except LuaParseError as err:
            if err.incomplete:
                prompt = ">> "
                continue
            runtime.stderr.write(err.format_message() + "\n")
            runtime.stderr.flush()
            buffer.clear()
            prompt = "> "
            continue
        runtime._current_source_text = source
        try:
            results = run_generator(runtime.exec_chunk(chunk))
            if expr_mode and results:
                runtime.lib_print(*results)
        except LuaExit as ex:
            return ex.code
        except LuaRuntimeError as err:
            runtime.stderr.write(format_runtime_error("stdin", err) + "\n")
            runtime.stderr.flush()
        buffer.clear()
        prompt = "> "


def run_chunk_text(
    runtime: Runtime,
    source_name: str,
    text: str,
    env: Optional[LuaTable] = None,
) -> list[Any]:
    runtime._current_source_text = text
    chunk = compile_chunk(source_name, text)
    return run_generator(runtime.exec_chunk(chunk, env))


def process_init(runtime: Runtime, ignore_env: bool) -> Optional[int]:
    if ignore_env:
        return None
    init = os.getenv("LUA_INIT_5_5")
    if init is None:
        init = os.getenv("LUA_INIT")
    if init is None:
        return None
    try:
        if init.startswith("@"):
            path = init[1:]
            try:
                text = pathlib.Path(path).read_text()
            except OSError as exc:
                runtime.stderr.write(f"{runtime.argv0}: cannot open {path}: {exc.strerror}\n")
                return 1
            run_chunk_text(runtime, path, text)
        else:
            run_chunk_text(runtime, "LUA_INIT", init)
    except LuaRuntimeError as err:
        runtime.stderr.write(format_runtime_error(runtime.argv0, err).replace(f"{runtime.argv0}: ", f"{runtime.argv0}: ") + "\n")
        return 1
    except LuaParseError as err:
        runtime.stderr.write(f"{runtime.argv0}: {err.format_message()}\n")
        return 1
    except LuaExit as ex:
        return ex.code
    return None


def main(argv: Optional[list[str]] = None) -> int:
    argv = list(sys.argv if argv is None else argv)
    argv0 = argv[0]
    args = argv[1:]
    interactive = False
    show_version = False
    ignore_env = False
    warnings = False
    exec_chunks: list[str] = []
    load_modules: list[tuple[str, str]] = []
    processed_tokens: list[str] = []
    script: Optional[str] = None
    script_args: list[str] = []
    explicit_stdin = False
    stop_options = False
    i = 0
    while i < len(args):
        arg = args[i]
        if not stop_options and arg == "--":
            processed_tokens.append(arg)
            stop_options = True
            i += 1
            continue
        if not stop_options and arg == "-":
            script = "-"
            explicit_stdin = True
            i += 1
            script_args = args[i:]
            break
        if not stop_options and arg.startswith("-") and arg != "-":
            if arg == "-i":
                interactive = True
                processed_tokens.append(arg)
                i += 1
                continue
            if arg == "-v":
                show_version = True
                processed_tokens.append(arg)
                i += 1
                continue
            if arg == "-E":
                ignore_env = True
                processed_tokens.append(arg)
                i += 1
                continue
            if arg == "-W":
                warnings = True
                processed_tokens.append(arg)
                i += 1
                continue
            if arg.startswith("-e"):
                if arg == "-e":
                    if i + 1 >= len(args):
                        sys.stderr.write(usage(argv0, "'-e' needs argument") + "\n")
                        return 1
                    code = args[i + 1]
                    processed_tokens.extend([arg, code])
                    exec_chunks.append(code)
                    i += 2
                    continue
                code = arg[2:]
                processed_tokens.append(arg)
                exec_chunks.append(code)
                i += 1
                continue
            if arg.startswith("-l"):
                if arg == "-l":
                    if i + 1 >= len(args):
                        sys.stderr.write(usage(argv0, "'-l' needs argument") + "\n")
                        return 1
                    modarg = args[i + 1]
                    processed_tokens.extend([arg, modarg])
                    i += 2
                else:
                    modarg = arg[2:]
                    processed_tokens.append(arg)
                    i += 1
                if "=" in modarg:
                    global_name, module_name = modarg.split("=", 1)
                else:
                    global_name = modarg.split(".")[-1]
                    module_name = modarg
                load_modules.append((global_name, module_name))
                continue
            sys.stderr.write(usage(argv0, f"unrecognized option '{arg}'") + "\n")
            return 1
        script = arg
        i += 1
        script_args = args[i:]
        break

    runtime = Runtime(argv0, sys.stdin, sys.stdout, sys.stderr, warnings_enabled=warnings)
    set_arg_table(runtime, build_arg_table(argv0, processed_tokens, script, script_args))

    if show_version:
        sys.stdout.write(VERSION_BANNER + "\n")
        sys.stdout.flush()

    init_rc = process_init(runtime, ignore_env)
    if init_rc is not None:
        return init_rc

    if interactive:
        sys.stdout.write(VERSION_BANNER + "\n")
        sys.stdout.flush()

    try:
        for global_name, module_name in load_modules:
            value = run_generator(runtime.lib_require(module_name))[0]
            runtime.table_set(runtime.globals, global_name, value)
        for code in exec_chunks:
            run_chunk_text(runtime, "(command line)", code)
        if script is not None:
            if explicit_stdin:
                text = sys.stdin.read()
                run_chunk_text(runtime, "stdin", text)
            else:
                try:
                    text = pathlib.Path(script).read_text()
                except OSError as exc:
                    sys.stderr.write(f"{argv0}: cannot open {script}: {exc.strerror}\n")
                    return 1
                run_chunk_text(runtime, script, text)
        elif not exec_chunks and not load_modules:
            if sys.stdin.isatty():
                return run_repl(runtime)
            text = sys.stdin.read()
            if text:
                try:
                    run_chunk_text(runtime, "stdin", text)
                except (LuaRuntimeError, LuaParseError) as err:
                    if isinstance(err, LuaRuntimeError):
                        sys.stderr.write(format_runtime_error(argv0, err) + "\n")
                    else:
                        sys.stderr.write(f"{argv0}: {err.format_message()}\n")
                    return 0
        if interactive:
            return run_repl(runtime)
        return 0
    except LuaExit as ex:
        return ex.code
    except LuaParseError as err:
        sys.stderr.write(f"{argv0}: {err.format_message()}\n")
        return 1
    except LuaRuntimeError as err:
        sys.stderr.write(format_runtime_error(argv0, err) + "\n")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

