    command = 'exec -a ./executable ./executable.orig ' + ' '.join(shlex.quote(a) for a in args)
    p = subprocess.run(['bash', '-lc', command], input=stdin, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    return p.returncode, p.stdout, p.stderr

def run_new(args, stdin=None, extra_env=None):
    env = os.environ.copy();
    if extra_env: env.update(extra_env)
    p = subprocess.run(['./executable', *args], input=stdin, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    return p.returncode, p.stdout, p.stderr

for name, args, stdin, extra_env in cases:
    a = run_orig(args, stdin, extra_env)
    b = run_new(args, stdin, extra_env)
    print(name, a == b, repr(a[1]), repr(b[1]))
